1	using System;
2	using System.IO;
3	using Avalonia.Media.Imaging;
4	using Klippy.Models;
5	
6	namespace Klippy.ViewModels;
7	
8	/// <summary>Row presentation of a captured clip.</summary>
9	public partial class ClipViewModel : RowViewModel
10	{
11	    /// <summary>Wide enough to stay crisp on the row, small enough that decoding is cheap.</summary>
12	    private const int ThumbnailWidth = 96;
13	
14	    private readonly Func<ClipEntry, byte[]?>? _loadImage;
15	    private Bitmap? _thumbnail;
16	    private bool _thumbnailAttempted;
17	
18	    public ClipEntry Model { get; }
19	
20	    public ClipViewModel(ClipEntry model, Func<ClipEntry, byte[]?>? loadImage = null)
21	    {
22	        Model = model;
23	        _loadImage = loadImage;
24	    }
25	
26	    public override string Label => Model.Label;
27	    public override string Content => Model.Text;
28	
29	    public bool IsPinned => Model.IsPinned;
30	    public bool IsImage => Model.Kind == ClipKind.Image;
31	    public bool IsFiles => Model.Kind == ClipKind.Files;
32	
33	    /// <summary>
34	    /// A clip of files is nothing but paths, and a picture has none; only text has to be
35	    /// read to find out.
36	    /// </summary>
37	    protected override bool ReadsAsAPath() => Model.Kind switch
38	    {
39	        ClipKind.Files => Model.Files.Length > 0,
40	        ClipKind.Image => false,
41	        _ => base.ReadsAsAPath(),
42	    };
43	
44	    /// <summary>Where it was copied from, e.g. "chrome". Empty when the owner could not be identified.</summary>
45	    public string SourceApp => Model.SourceApp;
46	
47	    /// <summary>Marks clips that carry formatting, matching the "md" marker on snippet rows.</summary>
48	    public bool HasHtml => Model.Kind == ClipKind.Text && Model.Html is { Length: > 0 };
49	
50	    /// <summary>The kind marker on the row: "png", "bmp" or a file count.</summary>
51	    public string KindMarker => Model.Kind switch
52	    {
53	        ClipKind.Image => Model.BlobFormat.ToLowerInvariant(),
54	        ClipKind.Files => Model.Files.Length == 1 ? "file" : $"{Model.Files.Length} files",
55	        _ => "",
56	    };
57	
58	    public bool HasKindMarker => KindMarker.Length > 0;
59	
60	    /// <summary>
61	    /// A small preview of an image clip, decoded once and only when the row is first
62	    /// shown — a history of screenshots would otherwise decode every picture it holds
63	    /// the moment the list opens.
64	    /// </summary>
65	    public Bitmap? Thumbnail
66	    {
67	        get
68	        {
69	            if (_thumbnailAttempted || !IsImage) return _thumbnail;
70	            _thumbnailAttempted = true;
71	
72	            if (_loadImage?.Invoke(Model) is not { Length: > 0 } bytes) return null;
73	
74	            try
75	            {
76	                using var stream = new MemoryStream(bytes);
77	                _thumbnail = Bitmap.DecodeToWidth(stream, ThumbnailWidth);
78	            }
79	            catch (Exception)
80	            {
81	                // An unreadable blob costs a thumbnail, not the row: the clip can still be
82	                // copied back, since that hands over the bytes untouched.
83	                _thumbnail = null;
84	            }
85	            return _thumbnail;
86	        }
87	    }
88	
89	    /// <summary>
90	    /// Coarse age, e.g. "now", "5m", "3h", "2d". Rebuilt whenever the list refreshes
91	    /// rather than ticking on a timer — a clipboard history is read in glances, and a
92	    /// row that rewrites itself while being looked at is worse than one a minute stale.
93	    /// </summary>
94	    public string Age
95	    {
96	        get
97	        {
98	            var elapsed = DateTimeOffset.UtcNow - Model.CapturedAt;
99	
100	            if (elapsed < TimeSpan.FromMinutes(1)) return "now";
101	            if (elapsed < TimeSpan.FromHours(1)) return $"{(int)elapsed.TotalMinutes}m";
102	            if (elapsed < TimeSpan.FromDays(1)) return $"{(int)elapsed.TotalHours}h";
103	            return $"{(int)elapsed.TotalDays}d";
104	        }
105	    }
106	}
