225	    private static string ReadVersionText()
226	    {
227	        var version = typeof(MainViewModel).Assembly
228	            .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
229	
230	        if (string.IsNullOrWhiteSpace(version)) return string.Empty;
231	
232	        // The SDK appends "+<commit sha>" when the repo is a git checkout, which is noise
233	        // in a title bar.
234	        var build = version.IndexOf('+');
235	        return "v" + (build >= 0 ? version[..build] : version);
236	    }
