317	    partial void OnFilterTextChanged(string value)
318	    {
319	        // A search (and a quick-code) looks at every snippet, so a live tag filter is
320	        // dropped rather than silently ignored — the chips always show what the list
321	        // is actually doing.
322	        if (value.Length > 0 && _activeTag != AllTag)
323	            ActivateTag(AllTag);
