325	        // Typing re-asks what the line could still become. A line that completes nothing
326	        // closes the MRU, which is what hands the arrow keys back to the list: an
327	        // ordinary search is not a command and must not have to fight one for them.
328	        if (!_writingFilter)
329	        {
330	            if (value.Length > 0) OpenCommands(selectFirst: false);
331	            else CloseCommands(restore: false);
332	        }
