358	    /// <summary>
359	    /// Decides whether the line that was just searched for should also be offered as
360	    /// something to run.
361	    ///
362	    /// An item that matches beats the offer — but only where the line could have been
363	    /// meant as a search for that item. "lock" could: a snippet called "Lock the server
364	    /// room door" answers to it, and keeps it a filter. <c>D:\work\tools\</c> could not,
365	    /// and a snippet whose body merely mentions that folder has not been asked for by
366	    /// someone typing the folder's own path.
367	    ///
368	    /// An item also wins when it <em>is</em> the line — a snippet whose text is the very
369	    /// link you typed was plausibly the thing you were looking for, however literal the
370	    /// line. Merely mentioning it is not being it.
371	    ///
372	    /// The one place all of that is dropped is the clipboard history, where the clips
373	    /// themselves are mostly paths and links: there a line that looks like one is far more
374	    /// likely to be someone hunting for the clip they copied than an instruction, so a
375	    /// matching clip wins whatever was typed.
376	    ///
377	    /// A line that names a define in the variables file is offered as each of its values
378	    /// as well, below whatever the line itself was offered as — see
379	    /// <see cref="UnmatchedSearch.PlanDefine"/>. Those stand the way quit does: a matching
380	    /// row does not take them away, and does keep the selection.
381	    /// </summary>
382	    private void UpdateOffer()
383	    {
384	        // Klippy's own quit, ahead of the gate below and deliberately outside it: that
385	        // setting governs handing typed text to the machine, and closing the app is
386	        // neither typed text nor the machine's business. Unlike the rest of this method, no
387	        // matching item beats it here: the footer link and the tray are the only other ways
388	        // out, and a snippet that merely mentions "quit" — in its label, content or tag —
389	        // must not silently take the keyboard route away. A matching row still keeps the
390	        // selection and answers to Enter, exactly as it does beside any other offer; it is
391	        // only the offer's own standing that stops depending on the list being empty.
392	        if (CanQuit && Names(FilterText, QuitWord))
393	        {
394	            ShowOffers([OfferViewModel.Quit()], takeSelection: false);
395	            return;
396	        }
397	
398	        if (!_prefs.ExecuteUnmatched || !CanExecuteUnmatched)
399	        {
400	            ShowOffers([], takeSelection: false);
401	            return;
402	        }
403	
404	        // Only a rooted path ever reaches the file system here, so an ordinary search word
405	        // costs the same as it did when this ran on an empty list alone — unless it is the
406	        // name of a define, which is what asks for the values it stands for to be looked at.
407	        //
408	        // The same environment a marked item is resolved against, variables file included:
409	        // two routes to the same launcher must not disagree about what %ws% means any more
410	        // than about what %LOCALAPPDATA% does.
411	        var variables = KlippyVariables.Current;
412	        var environment = variables.Ahead(EnvironmentProbe.Real);
413	        var plans = new List<ExecutionPlan>();
414	
415	        // A line that is the name of a define, offered as each value it stands for.
416	        // Snippets only: in the history a line is someone hunting for a clip, and a name is
417	        // no less likely to be that than a path is.
418	        var defines = IsHistoryMode
419	            ? []
420	            : UnmatchedSearch.PlanDefine(FilterText, variables, _prefs.ExecuteVerifyPaths,
421	                environment: environment, alsoOpens: _prefs.AlsoOpens);
422	
423	        // Standing beside a list that still has rows in it, what the line itself names is
424	        // what Enter acts on — so the selection comes off the list, since a row that is not
425	        // getting the keystroke must not sit there wearing the badge that says it is. ↓
426	        // moves back in, and from there Enter activates the row as it always did.
427	        //
428	        // Where that is one of the define's own offers — %klippy% resolved to one of
429	        // klippy's values — the define's order stands in for it, so %klippy% and klippy put
430	        // the same thing on Enter. Anything else it named keeps its place at the top:
431	        // adding a define never changes what Enter did to a line before it.
432	        bool takeSelection = false;
433	        var plan = UnmatchedSearch.Plan(FilterText, _prefs.ExecuteVerifyPaths, environment: environment);
434	        if (plan.Kind != ExecutionKind.None)
435	        {
436	            bool beatenByAMatch = Filtered.Count > 0
437	                                  && (IsHistoryMode || UnmatchedSearch.CouldBeASearch(plan) || AnItemIsTheLine(plan));
438	            takeSelection = !beatenByAMatch;
439	            if (takeSelection && !defines.Any(d => UnmatchedSearch.IsSame(d, plan))) plans.Add(plan);
440	        }
441	
442	        // After the line's own offer, and not a reason to take the selection from a row, the
443	        // way quit is not: a bare name is an ordinary word — "app" is a search as often as
444	        // it is anything — and every snippet written with %app% in it answers to it. Being
445	        // shown is the whole of what a name is owed here: ↑ from the top row reaches it.
446	        foreach (var value in defines)
447	            if (!plans.Exists(p => UnmatchedSearch.IsSame(p, value)))
448	                plans.Add(value);
449	
450	        ShowOffers(plans.ConvertAll(p => new OfferViewModel(p)), takeSelection);
451	    }
452	
453	    /// <summary>
454	    /// Puts up what the line is offered as, in place of whatever was before. The top offer
455	    /// holds the selection whenever no row does — which, with nothing matching, is always —
456	    /// and <paramref name="takeSelection"/> says whether it takes the selection from a row.
457	    /// </summary>
458	    private void ShowOffers(IReadOnlyList<OfferViewModel> offers, bool takeSelection)
459	    {
460	        // Every keystroke comes through here, and nearly every one with nothing on offer
461	        // either side of it: nothing to tell the view.
462	        if (Offers.Count > 0 || offers.Count > 0)
463	        {
464	            Offers.Clear();
465	            foreach (var offer in offers)
466	            {
467	                // Numbered only where there is a choice to make, and only as far as a digit goes.
468	                if (offers.Count > 1 && Offers.Count < NumberedOffers) offer.Number = Offers.Count + 1;
469	                Offers.Add(offer);
470	            }
471	            OnPropertyChanged(nameof(Offer));
472	            OnPropertyChanged(nameof(HasOffers));
473	        }
474	
475	        _offerIndex = 0;
476	        if (takeSelection && Offers.Count > 0) SelectedSnippet = null;
477	        SyncOfferSelection();
478	    }
