511	    private void RefreshSnippets()
512	    {
513	        // "code argument…" invokes one snippet rather than filtering the list: the search
514	        // box has become a command line, so the words after the code are arguments for
515	        // its %P% placeholders and not search terms.
516	        if (TryInvoke()) return;
517	
518	        ClearArguments();
519	        var results = _store.Search(FilterText);
520	
521	        Filtered.Clear();
522	        foreach (var entry in results)
523	        {
524	            if (_activeTag != AllTag && !string.Equals(entry.Item.Tag, _activeTag, StringComparison.OrdinalIgnoreCase))
525	                continue;
526	
527	            Filtered.Add(RowFor(entry.Item));
528	        }
529	
530	        SnippetCountText = Filtered.Count == 1 ? "1 snippet" : $"{Filtered.Count} snippets";
531	    }
