533	    /// <summary>
534	    /// Shows just the snippet whose quick-code was typed, carrying whatever was typed
535	    /// after it. False when the line is not an invocation — no whitespace yet, or no
536	    /// snippet answers to that exact code — and the ordinary search runs instead.
537	    ///
538	    /// The variables file comes along, so an argument can name a define rather than
539	    /// spelling a path out: "r app" is the solution app names. Against the snippet as
540	    /// stored, because the item is half of the question — its %P:file% is what says which
541	    /// flavour of a name it wants. Resolved once, here, so the row's preview, a copy and a
542	    /// run all see the same argument: having them disagree about what a word meant would
543	    /// be worse than not resolving it at all.
544	    /// </summary>
545	    private bool TryInvoke()
546	    {
547	        if (!QuickInvocation.TryParse(FilterText, out var invocation) ||
548	            _store.FindByQuickCode(invocation.Code) is not { } snippet)
549	            return false;
550	
551	        var row = RowFor(snippet);
552	        if (!ReferenceEquals(_invoked, row)) ClearArguments();
553	
554	        _invoked = row;
555	        var variables = KlippyVariables.Current;
556	        row.SetArguments(invocation.ValuesFor(snippet.Content, variables), variables);
557	
558	        Filtered.Clear();
559	        Filtered.Add(row);
560	        SnippetCountText = "1 snippet";
561	        return true;
562	    }
