654	    private void ShowMode(bool history, string tag)
655	    {
656	        // The MRU belongs to the snippet command line, and leaving it this way is leaving
657	        // it empty-handed: the box goes back to what was actually typed rather than to
658	        // whichever recalled command was under the cursor when the view changed.
659	        CloseCommands(restore: true);
660	
661	        // Whether this changes what the list holds or only narrows it. Asked before
662	        // IsHistoryMode moves, or the answer would always be "only narrows it".
663	        bool narrowing = history == IsHistoryMode;
664	
665	        IsHistoryMode = history;
666	        ActivateTag(tag);
667	
668	        // What is in the box survives a change of mode: you are looking for the same
669	        // thing either way — "that connection string" is a question for the clips and for
670	        // the snippets alike — and retyping it to ask the other half is an errand. A tag
671	        // chip is not a change of mode but a narrowing of the one you are already in, and
672	        // it still clears, because a search drops the tag filter the moment you type and
673	        // the chips have to keep describing what the list is doing.
674	        if (narrowing) FilterText = "";
675	
676	        Refresh(); // FilterText may already have been empty, so nothing fired above
677	    }
