702	    /// <summary>
703	    /// Puts the item on the clipboard. <paramref name="record"/> says whether what is in the search box is the
704	    /// line that chose it, and so belongs in the command MRU — false for a shortcut, which names the snippet
705	    /// itself and has nothing to do with whatever happens to be typed. <paramref name="quiet"/> leaves the
706	    /// window as it is — no focus moved, nothing closed — for a hotkey pressed while an overlay is up. True
707	    /// when something was copied.
708	    /// </summary>
709	    private async Task<bool> CopyCore(RowViewModel? row, bool record, bool quiet = false)
710	    {
711	        CloseCommands(restore: false); // whatever route got here, the line has been chosen
712	
713	        CopyPayload payload;
714	        if (row is SnippetViewModel snippet)
715	        {
716	            // Local defines first, then macros, which is the order the execute path
717	            // resolves them in and for the same reason: a %ws% that arrives through %C%
718	            // is a value off the clipboard rather than a name the item asked to have
719	            // resolved.
720	            var template = KlippyVariables.Current.Expand(snippet.Model.Content);
721	
722	            // Macros resolve on the way to the clipboard, so what lands there is the
723	            // expansion — a half-typed invocation must never paste as "%P%".
724	            var content = await ResolveMacrosAsync(template, snippet.Arguments);
725	            payload = RichTextClipboard.BuildPayload(content, snippet.Model.IsMarkdown);
726	        }
727	        // A clip keeps whatever flavours it was captured with, so pasting it back gives
728	        // what the original copy would have — real files into Explorer, a picture into
729	        // an image editor, formatting into a rich-text box.
730	        else if (row is ClipViewModel clip) payload = BuildClipPayload(clip);
731	        else return false;
732	
733	        if (ClipboardWriter is { } write)
734	            await write(payload);
735	
736	        MarkUsed(row);
737	        if (record) RecordCommand();
738	
739	        ShowToast();
740	        if (quiet) return true;
741	        Copied?.Invoke();
742	
743	        // Read per copy rather than cached: the Settings overlay writes straight through
744	        // to the same instance, so a toggle applies to the very next copy.
745	        bool close = row is ClipViewModel
746	            ? _prefs.CloseAfterClipboardCopy
747	            : _prefs.CloseAfterSnippetCopy;
748	        if (close) CloseRequested?.Invoke();
749	        return true;
750	    }
751	
752	    /// <summary>
753	    /// Runs the item: its link opens in whatever opens its kind, or the document,
754	    /// script or application it names opens or starts, with the same macros a copy would
755	    /// have resolved.
756	    /// Reached by triggering an item marked Execute.
757	    ///
758	    /// The item's stored text goes to the execution engine together with the typed
759	    /// arguments, rather than the expansion a copy would make — only the engine knows
760	    /// whether a value is about to land in a URL's query string or in a script's
761	    /// argument list, and those want it escaped differently.
762	    /// </summary>
763	    [RelayCommand]
764	    private Task Execute(RowViewModel? row) => ExecuteCore(row, record: true);
765	
766	    /// <summary>
767	    /// Runs the item — see <see cref="Execute"/>. <paramref name="record"/> and <paramref name="quiet"/> as for
768	    /// <see cref="CopyCore"/>. True when it started.
769	    /// </summary>
770	    private async Task<bool> ExecuteCore(RowViewModel? row, bool record, bool quiet = false)
771	    {
772	        if (row is null) return false;
773	
774	        CloseCommands(restore: false);
775	
776	        if (Executor is not { } run)
777	        {
778	            // Nothing wired up to run things: say so rather than leaving Enter looking
779	            // broken on an item that is marked to run.
780	            ShowToast(CannotExecuteHere, isError: true);
781	            return false;
782	        }
783	
784	        var text = row.Template;
785	
786	        // The variables file sits in front of the machine's own environment, so %ws% names
787	        // WebStorm on the run path exactly as %LOCALAPPDATA% names a folder. Handing it to
788	        // the policy rather than expanding here keeps the first-word-only rule: an
789	        // argument's percent signs stay the user's own.
790	        var plan = WithPreferences(ExecutionPolicy.Plan(
791	            text,
792	            row.Arguments,
793	            await ReadClipboardForAsync(text),
794	            environment: KlippyVariables.Current.Ahead(EnvironmentProbe.Real),
795	            alsoOpens: _prefs.AlsoOpens)) with
796	        {
797	            // The item's own marker, unlike the preferences: whether this one needs the
798	            // administrator's rights is a fact about it. Whether it can have them — a
799	            // script or an application, on Windows — is the launcher's to judge, and a
800	            // plan that cannot is refused there rather than started without them.
801	            Elevated = row.RunsAsAdministrator,
802	        };
803	
804	        if (plan.Kind == ExecutionKind.None)
805	        {
806	            ShowToast(plan.Problem, isError: true);
807	            return false;
808	        }
809	
810	        var result = await run(plan);
811	        ShowToast(result.Message, isError: !result.Started);
812	        if (!result.Started) return false;
813	
814	        MarkUsed(row);
815	        if (record) RecordCommand();
816	        if (quiet) return true;
817	        Copied?.Invoke();
818	
819	        // Executing is a launcher gesture: the browser or the script is where you are
820	        // going next, so Klippy gets out of the way — the copy preferences are about
821	        // staying put to copy a second thing, which does not apply here.
822	        CloseRequested?.Invoke();
823	        return true;
824	    }
