829	    /// <summary>
830	    /// Shows the file or folder a row names in Explorer or Finder: a folder opens, a file is
831	    /// selected in the folder it is in. Any row may ask, marked or not, snippet or clip —
832	    /// showing something runs nothing, so it needs no marker to have been put there first.
833	    ///
834	    /// A snippet is read as a copy would put it on the clipboard, variables and macros
835	    /// filled in, since that text is what the row stands for. A clip of files shows the
836	    /// first of them, which is the one its row is named after; a clip of text is the path
837	    /// it holds, read as if it had been pasted into the search box.
838	    /// </summary>
839	    [RelayCommand]
840	    private async Task Reveal(RowViewModel? row)
841	    {
842	        if (row is null) return;
843	
844	        CloseCommands(restore: false);
845	
846	        if (Executor is not { } run)
847	        {
848	            ShowToast(CannotExecuteHere, isError: true);
849	            return;
850	        }
851	
852	        var text = row switch
853	        {
854	            SnippetViewModel snippet => await ResolveMacrosAsync(
855	                KlippyVariables.Current.Expand(snippet.Model.Content), snippet.Arguments),
856	            ClipViewModel { Model.Kind: ClipKind.Files, Model.Files: [var first, ..] } => first,
857	            ClipViewModel { Model.Kind: ClipKind.Text } clip => clip.Content,
858	            _ => null, // a picture, or a file clip with no files: nothing on disk to point at
859	        };
860	
861	        var plan = ExecutionPolicy.PlanReveal(
862	            text, environment: KlippyVariables.Current.Ahead(EnvironmentProbe.Real));
863	
864	        if (plan.Kind == ExecutionKind.None)
865	        {
866	            ShowToast(plan.Problem, isError: true);
867	            return;
868	        }
869	
870	        var result = await run(plan);
871	        ShowToast(result.Message, isError: !result.Started);
872	        if (!result.Started) return;
873	
874	        // Not marked as used, and nothing recorded: looking at where a file is leaves what
875	        // the item is for where it was. The window gets out of the way as it does for a
876	        // run, since the file manager is where you are going next.
