934	    /// mentioning it — by the line as typed, or by what that line resolved to, so
935	    /// <c>%APPDATA%</c> and the folder it expands to are the same request.
936	    /// </summary>
937	    private bool AnItemIsTheLine(ExecutionPlan plan)
938	    {
939	        var typed = UnmatchedSearch.Unquote(FilterText.Trim());
940	
941	        foreach (var row in Filtered)
942	            if (Names(row.Label, typed) || Names(row.Content, typed)
943	                || Names(row.Label, plan.Target) || Names(row.Content, plan.Target))
944	                return true;
945	
946	        return false;
