999	    /// reports in the same toast. The only difference is where the plan came from.
1000	    ///
1001	    /// Quit is the one offer with no plan to hand over: it is Klippy closing rather than
1002	    /// Klippy starting something, so it turns back here and never reaches the launcher.
1003	    /// </summary>
1004	    private async Task Run(OfferViewModel offer)
1005	    {
1006	        CloseCommands(restore: false);
1007	
1008	        if (offer.IsQuit)
1009	        {
1010	            QuitRequested?.Invoke();
1011	            return;
1012	        }
1013	
1014	        if (Executor is not { } run)
1015	        {
1016	            ShowToast(CannotExecuteHere, isError: true);
1017	            return;
1018	        }
1019	
1020	        var result = await run(WithPreferences(offer.Plan));
1021	        ShowToast(result.Message, isError: !result.Started);
1022	        if (!result.Started) return; // the window stays up, or the message is never read
1023	
1024	        RecordCommand();
