    [AvaloniaFact]
    public void Shot()
    {
        var rtb = new RenderTargetBitmap(new PixelSize(600, 400));
        using (var ctx = rtb.CreateDrawingContext())
        {
            ctx.FillRectangle(Brushes.SteelBlue, new Rect(0, 0, 600, 400));
            ctx.FillRectangle(Brushes.Orange, new Rect(100, 80, 300, 200));
        }
        var ms = new MemoryStream(); rtb.Save(ms);
        var store = new SnippetStore(Path.Combine(Path.GetTempPath(), $"s{Guid.NewGuid():N}.json"), seedIfEmpty: false);
        var history = ClipHistoryStore.InMemory();
        history.AddImage(ms.ToArray(), "PNG", 600, 400, "snippingtool");
        var vm = new MainViewModel(store, history);
        vm.ShowHistory();
        var window = new MainWindow { DataContext = vm };
        window.Show();
        vm.TogglePreviewCommand.Execute(null);
        Dispatcher.UIThread.RunJobs();
        var dir = Environment.GetEnvironmentVariable("SHOTDIR")!;
        window.CaptureRenderedFrame()!.Save(Path.Combine(dir, "pane.png"));
        vm.PreviewImageCommand.Execute(vm.SelectedSnippet);
        Dispatcher.UIThread.RunJobs();
        window.CaptureRenderedFrame()!.Save(Path.Combine(dir, "overlay.png"));
    }
}
